  "Keine Einarbeitung": "Nessuna formazione",
  "Was das heisst": "Cosa significa",
  "Wer Ihren Agent baut, betreut ihn auch.": "Chi costruisce il Suo agente lo segue anche.",
  "AVV, EU-Verarbeitung, wo verfügbar, Löschfristen nach Ihrer Vorgabe.": "Accordo sul trattamento (DPA), trattamento nell'UE dove disponibile, tempi di conservazione secondo le Sue indicazioni.",
  "Anfragen, Buchungen und gesparte Zeit auf einer Seite.": "Richieste, prenotazioni e tempo risparmiato in un'unica pagina.",
  "Kleine Anpassungen meist am selben Tag.": "Piccoli adattamenti di solito in giornata.",
  "Sie bekommen einen fertigen Agent, keine Software.": "Riceve un agente pronto, non un software.",
  "Keine Mindestlaufzeit.": "Nessuna durata minima.",
  "Was den Unterschied macht": "Cosa fa la differenza",
  "Termine direkt im Gespräch": "Appuntamenti direttamente durante la chiamata",
  "Der Agent prüft freie Zeiten und bucht, verschiebt oder storniert Termine direkt in Ihrem Kalender.": "L'agente verifica gli orari liberi e prenota, sposta o annulla gli appuntamenti direttamente nel Suo calendario.",
  "Direkt angebunden: Google Kalender, Cal.com, Calendly und GoHighLevel; Outlook und Branchen-Buchungssysteme über Automation oder Schnittstelle, sofern verfügbar. Bestätigung und Erinnerung per SMS oder E-Mail.": "Integrazione diretta: Google Calendar, Cal.com, Calendly e GoHighLevel; Outlook e i sistemi di prenotazione di settore tramite automazione o interfaccia, se disponibile. Conferma e promemoria via SMS o e-mail.",
  "Antworten aus Ihren Inhalten": "Risposte dai Suoi contenuti",
  "Der Agent beantwortet Fragen mit Ihrer Website, Preisliste und Ihren Dokumenten, statt zu raten.": "L'agente risponde alle domande con il Suo sito web, il listino prezzi e i Suoi documenti, invece di tirare a indovinare.",
  "Plattformwerte: bis 500 Webseiten mit automatischem Einlesen, 25 Dateien à 50 MB (PDF, Word, Excel, Bilder u. a.) und eigene Textbausteine. Tabellen und Überschriften werden sauber zerlegt, der Abruf ist im Transkript sichtbar, und Wissensdatenbanken lassen sich einzelnen Gesprächsschritten zuweisen.": "Valori della piattaforma: fino a 500 pagine web con lettura automatica, 25 file da 50 MB ciascuno (PDF, Word, Excel, immagini e altro) e blocchi di testo propri. Tabelle e titoli vengono suddivisi in modo pulito, la consultazione è visibile nella trascrizione e le knowledge base si possono assegnare a singoli passaggi della conversazione.",
  "Mehrsprachig mit automatischer Erkennung": "Multilingue con riconoscimento automatico",
  "Der Agent erkennt die Sprache Ihrer Kunden und antwortet darin, natürlich auch auf Deutsch.": "L'agente riconosce la lingua dei Suoi clienti e risponde in quella lingua, naturalmente anche in italiano.",
  "Plattformwert: 55 Sprachen, darunter Deutsch, Französisch, Italienisch und Englisch. Sprachen sind pro Agent einzeln wählbar, ein Sprachwechsel mitten im Gespräch ist mit passenden Erkennungsanbietern möglich; einsprachige Agenten erkennen am genauesten.": "Valore della piattaforma: 55 lingue, tra cui tedesco, francese, italiano e inglese. Le lingue si scelgono singolarmente per ogni agente; il cambio di lingua a metà conversazione è possibile con provider di riconoscimento adatti. Gli agenti monolingue riconoscono con maggiore precisione.",
  "Erinnert sich an Stammkunden": "Ricorda i clienti abituali",
  "Meldet sich ein Kunde erneut, weiss der Agent, worum es beim letzten Mal ging.": "Quando un cliente si rifà vivo, l'agente sa di cosa si era parlato l'ultima volta.",
  "Kurzakte pro Kontakt (bis 2.000 Zeichen) wird nach Anrufen und SMS-Chats fortgeschrieben und ist für mehrere Agenten lesbar; bekannte Angaben müssen nicht neu erfragt werden. Die Speicherung lässt sich abschalten.": "Una breve scheda per contatto (fino a 2.000 caratteri) viene aggiornata dopo chiamate e chat SMS ed è leggibile da più agenti; le informazioni già note non vanno richieste di nuovo. La memorizzazione si può disattivare.",
  "Haben Sie Freitag noch etwas frei?": "Avete ancora qualcosa di libero venerdì?",
  "Ja, um 10:00 oder 15:30 Uhr. Was passt Ihnen?": "Sì, alle 10:00 o alle 15:30. Cosa preferisce?",
  "Kalender · Fr 15:30 gebucht": "Calendario · ven 15:30 prenotato",
  "Was kostet eine Gesichtsbehandlung?": "Quanto costa un trattamento viso?",
  "Die klassische Behandlung kostet {{m:95}} und dauert 60 Minuten.": "Il trattamento classico costa {{m:95}} e dura 60 minuti.",
  "Quelle · Preisliste.pdf": "Fonte · Listino.pdf",
  "Aus Ihrer Preisliste": "Dal Suo listino prezzi",
  "Do you have a room for two nights?": "Do you have a room for two nights?",
  "Yes, from Friday. Shall I hold a double room for you?": "Yes, from Friday. Shall I hold a double room for you?",
  "Sprache erkannt · Englisch": "Lingua rilevata · inglese",
  "Antwort in Kundensprache": "Risposta nella lingua del cliente",
  "Hallo, hier ist Frau Keller.": "Buongiorno, sono la signora Keller.",
  "Schön, von Ihnen zu hören. Wieder Balayage wie im März?": "Che piacere sentirLa. Di nuovo un balayage come a marzo?",
  "Stammkundin erkannt": "Cliente abituale riconosciuta",
  "In Zahlen": "In cifre",
  "Viel drin. Wenig zu tun.": "Tanto incluso. Poco da fare.",
  "in 12 Bereichen": "in 12 aree",
  "Plattformwert": "Valore della piattaforma",
