  "Filter zurücksetzen": "Azzera i filtri",
  "Hinweise zu Werten und Datenschutz": "Note su valori e privacy",
  "Sprachen, Antwortzeit und Verfügbarkeit (über 99,9 %) sind Plattformwerte. Zertifizierungen wie SOC 2 oder ISO 27001 hält die zugrunde liegende Plattform. Norra bietet AVV, EU-Verarbeitung, wo verfügbar, Schwärzung und Löschfristen nach Ihrer Vorgabe.": "Lingue, tempi di risposta e disponibilità (oltre il 99,9 %) sono valori della piattaforma. Certificazioni come SOC 2 o ISO 27001 sono detenute dalla piattaforma sottostante. Norra offre accordo sul trattamento (DPA), elaborazione nell'UE ove disponibile, oscuramento e tempi di conservazione secondo le Sue indicazioni.",
