  "Wovon hängt der Preis ab?": "Da cosa dipende il prezzo?",
  "Von Anbindungen, Sprachen und Standorten. Nach dem Erstgespräch gilt ein Festpreis.": "Da integrazioni, lingue e sedi. Dopo il primo colloquio vale un prezzo fisso.",
  "Was kostet der Verbrauch?": "Quanto costa il consumo?",
  "Ein Anruf von vier Minuten {{p:voice-agent.perUnit*4}}, ein Chat mit 14 Nachrichten rund {{p:chatbot.perUnit*14~2}}.": "Una chiamata di quattro minuti {{p:voice-agent.perUnit*4}}, una chat con 14 messaggi circa {{p:chatbot.perUnit*14~2}}.",
  "Gibt es eine Grundgebühr?": "C'è un canone base?",
  "Nur beim Voice Agent: {{p:voice-agent.monthly}} pro Monat für Rufnummer und Betrieb. Die Website kostet {{p:website.monthly}} pro Monat für Hosting und Pflege.": "Solo per il Voice Agent: {{p:voice-agent.monthly}} al mese per numero di telefono e gestione. Il sito web costa {{p:website.monthly}} al mese per hosting e manutenzione.",
