  "Haben Sie morgen um 10 Uhr frei?": "Domani alle 10 avete posto?",
  "Ja, 10 Uhr ist frei. Darf ich Ihren Namen notieren?": "Sì, alle 10 c'è posto. Posso annotare il Suo nome?",
