  "Gesparte Stunden pro Monat {h}, Wert der Zeit {value}, gerettete Aufträge {won}, Amortisation {amort}.": "Ore risparmiate al mese {h}, valore del tempo {value}, ordini recuperati {won}, rientro dell'investimento {amort}.",
